/**
 * Format timestamp to HH:MM AM/PM
 */ function formatTime(date) {
    if (!date) return '';
    const d = new Date(date);
    let hour = d.getHours();
    let minute = d.getMinutes().toString().padStart(2, '0');
    let period = 'AM';
    if (hour >= 12) {
        period = 'PM';
        hour = hour - 12;
    }
    if (hour === 0) hour = 12;
    return `${hour}:${minute} ${period}`;
}
